/* Playable development proposal; all progress is reset when this review page reloads. */
const VentureDevelopmentUI=(()=>{
    const M=MageVentureDevelopment;let selected='mine',tab='production',serial=0;
    const data=()=>state.ventureDevelopment;
    const number=n=>Number(n.toFixed(1)).toLocaleString('en');
    const name=id=>id==='mine'?'Moonstone mine':'Silverfin pond';
    const glyphMaterial=id=>{const r=M.find(id);return `<i class="material-glyph ${r.venture}" style="--material:${r.color}" aria-hidden="true"></i>`;};
    const stock=id=>`${glyphMaterial(id)}<span>${M.find(id).name}</span><b>${Math.floor(data().stock[id]).toLocaleString('en')}</b>`;
    const cost=items=>Object.entries(items).map(([id,n])=>`<span>${M.find(id)?glyphMaterial(id):ui(id,'inline-icon')} ${n} ${M.find(id)?.name||({ore:'Ore',pearls:'Pearls'})[id]}</span>`).join('');
    const command=(action,target,label,q,extra='')=>`<button class="rune-button ${extra}" data-v-command="${action}" data-v-target="${target}" aria-label="${action==='refine'?'Refine '+M.recipes.find(r=>r.id===target).name:action==='stock'?'Shelter 5 '+M.find(target).name:label}" ${q.ok?'':'disabled'}>${label}</button>`;
    function workers(id){const all=state.ventureSpirits.owned.filter(s=>s.assigned===id);return `<div class="spirit-worker-row"><span class="base-workers" aria-label="${id==='mine'?state.mining:state.fishing} base spirits always working">${sprite('spirit')}<b>${id==='mine'?state.mining:state.fishing}</b></span><span class="worker-divider"></span><button class="assigned-roster" data-spirit-list="${id}" aria-label="Manage ${all.length} loot spirits assigned to ${name(id)}">${all.slice(0,3).map(w=>sprite(MageVentureSpirits.find(w.kind).art)).join('')||'<span class="add-spirit">+</span>'}<span>${all.length?all.length+' loot':'Assign'}<small>Spirits</small></span><b>›</b></button></div>`;}
    function overview(){const d=data(),rates=M.production(d,MageVentureSpirits.production(state,state.ventureSpirits));return `<section class="page ventures-page spirit-ventures venture-development"><div class="compact-heading">${title('Ventures')}<button class="text-button" data-view="spirits">${sprite('spirit')} Spirits ›</button></div>${['mine','pond'].map(id=>{const v=d[id],r=M.find(v.selected),next=M.resources.find(r=>r.venture===id&&r.level===v.level+1);return `<section class="venture-card"><button class="venture-open" data-v-open="${id}" aria-label="Develop ${name(id)}"><span class="venture-site-art">${sprite(id)}</span><span><small>${id==='mine'?'DEPTH':'HABITAT'} ${v.level} / 4</small><strong>${name(id)}</strong><span class="venture-current">${glyphMaterial(r.id)} ${r.name} <b>${number(rates[r.id])}/min</b></span></span><b>›</b></button><div class="venture-next"><span>${next?'Next: '+next.name:'All resources unlocked'}</span><button data-v-open="${id}" data-v-open-tab="craft" class="text-button">${id==='mine'?'Refinery':'Sanctuary'} ›</button></div>${workers(id)}</section>`;}).join('')}<p class="venture-footnote">Choose what to produce. Build something new.</p></section>`;}
    function expand(id){const v=data()[id],q=M.quote(state,'upgrade',id),next=M.find(q.next);return `<section class="venture-expansion"><div><small>${v.level===4?'FULLY EXPANDED':'NEXT EXPANSION'}</small><strong>${next?'Unlock '+next.name:id==='mine'?'All veins open':'All habitats open'}</strong>${next?`<div class="venture-cost">${cost(q.cost)}</div><span class="venture-purpose">${id==='mine'?'New material for stronger focuses':'New species for your sanctuary'} · +1 base spirit</span>`:'<span class="venture-purpose">Earlier resources stay available.</span>'}</div>${command('upgrade',id,'Expand',q)}</section>`;}
    function production(id){const d=data(),v=d[id],rates=MageVentureSpirits.production(state,state.ventureSpirits),materials=M.production(d,rates),r=M.find(v.selected),base=id==='mine'?'ore':'pearls';return `<div class="venture-output"><span>${glyphMaterial(r.id)}<strong>${r.name}</strong><b>${number(materials[r.id])}/min</b></span><small>${Math.floor(d.stock[r.id])} stored · ${number(rates[base])} ${id==='mine'?'Ore':'Pearls'}/min</small></div><div class="venture-resource-grid" role="group" aria-label="Choose ${id==='mine'?'vein':'fishing habitat'}">${M.resources.filter(r=>r.venture===id).map(r=>{const unlocked=r.level<=v.level;return `<button data-v-command="select" data-v-target="${r.id}" aria-pressed="${v.selected===r.id}" ${unlocked?'':'disabled'}>${glyphMaterial(r.id)}<strong>${r.name}</strong><small>${unlocked?Math.floor(d.stock[r.id])+' stored':(id==='mine'?'Depth ':'Habitat ')+r.level}</small></button>`;}).join('')}</div>${expand(id)}<div class="venture-permanent">${id==='mine'?btn('+5 Spell power · 40 ore','buyDamage',false,state.ore<40):btn('+10 HP · 30 pearls','buyHp',false,state.pearls<30)}</div>${workers(id)}<button class="text-button venture-rate-info" data-action="${id==='mine'?'mineInfo':'pondInfo'}">${glyph('info')} Production & bonuses</button>`;}
    function refinery(){const d=data();return `<p class="venture-intro">Combine metals into permanent Spell power.</p><div class="venture-stock-strip">${M.resources.filter(r=>r.venture==='mine'&&r.level<=d.mine.level).map(r=>`<span>${stock(r.id)}</span>`).join('')}</div><div class="venture-recipes">${M.recipes.map(r=>{const q=M.quote(state,'refine',r.id),locked=d.mine.level<r.level;return `<section class="venture-recipe ${locked?'locked':''}"><div class="refinery-mark">${ui('power')}</div><div><strong>${r.name}</strong><small>${locked?'Unlock at depth '+r.level:'Crafted '+d.refined[r.id]+' · Permanent +'+r.power+' Spell power'}</small><div class="venture-cost">${cost(locked?r.cost:q.cost)}</div></div>${command('refine',r.id,ui('power','inline-icon')+' +'+r.power,q)}</section>`;}).join('')}</div><p class="venture-footnote">Keep older veins working toward your next focus.</p>`;}
    function sanctuary(){const d=data(),b=M.bonuses(d);return `<div class="sanctuary-summary">${sprite('pond')}<span><strong>${d.sanctuary.length} / 4 species sheltered</strong><small>Mine ×${number(b.mine)} · ${d.sanctuary.length===4?'Pearls ×1.25':'All 4: Pearls ×1.25'}</small></span></div><p class="venture-intro">Shelter each species once. Keep its bonus forever.</p><div class="sanctuary-grid">${M.resources.filter(r=>r.venture==='pond').map(r=>{const q=M.quote(state,'stock',r.id),done=d.sanctuary.includes(r.id),locked=r.level>d.pond.level;return `<section class="sanctuary-species ${done?'sheltered':''}">${glyphMaterial(r.id)}<strong>${r.name}</strong><small>${done?'✓ Mine +5%':locked?'Habitat '+r.level:Math.floor(d.stock[r.id])+' / 5 fish'}</small>${command('stock',r.id,done?'Sheltered':'Shelter 5',q,'secondary')}</section>`;}).join('')}</div><div class="venture-pond-synergy">${state.synergy?'<p class="venture-footnote">Pond upgrade: Mine ×1.25 · Active</p>':btn('Mine ×1.25 · 50 pearls','synergy',true,state.pearls<50)}</div>`;}
    function detail(){return `<section class="page venture-detail-page venture-development"><div class="venture-detail-heading"><button class="text-button" data-view="ventures" aria-label="Back to Ventures">‹</button>${sprite(selected)}<div><h2>${name(selected)}</h2><small>${selected==='mine'?'Choose veins · Refine metals':'Grow habitats · Shelter species'}</small></div></div><nav class="venture-tabs" aria-label="Venture activity"><button data-v-tab="production" aria-pressed="${tab==='production'}">${selected==='mine'?'Veins':'Habitats'}</button><button data-v-tab="craft" aria-pressed="${tab==='craft'}">${selected==='mine'?'Refinery':'Sanctuary'}</button></nav>${tab==='production'?production(selected):selected==='mine'?refinery():sanctuary()}</section>`;}
    function handle(el){if(el.dataset.vOpen){selected=el.dataset.vOpen;tab=el.dataset.vOpenTab||'production';go('ventureDetail');return true;}if(el.dataset.vTab){tab=el.dataset.vTab;render(true);phone.querySelector('[data-v-tab="'+tab+'"]')?.focus();return true;}if(el.dataset.vCommand){const action=el.dataset.vCommand,target=el.dataset.vTarget,q=M.quote(state,action,target),out=M.commit(state,{id:'venture-'+(++serial),action,target,token:q.token});if(out.ok){render(true);if(action!=='select')notify(action==='upgrade'?'Unlocked '+M.find(out.receipt.next).name:action==='refine'?'Permanent Spell power +'+out.receipt.power:'Species sheltered · Mine +5%');}else notify(out.reason||'Unable to complete action');return true;}return false;}
    function seed(advanced=false){state.ventureDevelopment=M.fresh();Object.assign(data().stock,{tin:24,reedfin:16});if(advanced){for(const id of ['mine','pond'])data()[id].level=3;data().mine.selected='gold';data().pond.selected='glassEel';for(const r of M.resources.filter(r=>r.level<=3))data().stock[r.id]=40;state.ore=600;state.pearls=300;state.mining=4;state.fishing=3;}go('ventures');}
    function materialSummary(materials){return materials?`<span class="return-venture-materials">${Object.entries(materials).map(([id,n])=>`<span>${glyphMaterial(id)}<strong>+${Math.floor(n).toLocaleString('en')}</strong> ${M.find(id).name}</span>`).join('')}</span>`:'';}
    function balances(){return `<div class="venture-stock-strip resources-materials">${M.resources.filter(r=>data()[r.venture].level>=r.level).map(r=>`<span>${stock(r.id)}</span>`).join('')}</div>`;}
    function refresh(){const active=document.activeElement,attributes=[...(active?.attributes||[])].filter(a=>a.name.startsWith('data-')).map(a=>'['+a.name+'="'+CSS.escape(a.value)+'"]').join('');render(true);if(attributes)phone.querySelector('button'+attributes)?.focus({preventScroll:true});}
    return {overview,detail,handle,seed,refresh,returnMaterials:()=>materialSummary(state.returned?.materials),materialSummary,balances};
})();
